// ===== KONFIGURACJA – ContentAI (Tadych) =====
const SUPABASE_URL = 'https://nyivgmimhwlhavdkgnzg.supabase.co';
const BASELINKER_INVENTORY_ID = 0;   // WSTAW: ID katalogu Baselinkera (Produkty → Katalogi → ID)
const ALLOWED_TYPES = ['ping', 'bl_catalog_list', 'bl_catalog_enrich', 'bl_import'];
// zadania dostępne tylko dla wybranych ról (pozostałe: każdy zalogowany)
const ROLES = { bl_catalog_list: ['akceptujacy', 'admin'], bl_catalog_enrich: ['akceptujacy', 'admin'] };

const req = $input.first().json;
const auth = req.headers?.authorization || '';
const jobId = String(req.body?.job_id || '');
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let reason = null;
if (!SUPABASE_URL.startsWith('https://')) reason = 'n8n: brak SUPABASE_URL w node KONFIGURACJA';
else if (!auth.startsWith('Bearer ')) reason = 'Brak tokenu użytkownika';
else if (!uuidRe.test(jobId)) reason = 'Nieprawidłowe ID zadania';
return [{ json: { ok: !reason, reason, supabase_url: SUPABASE_URL.replace(/\/$/, ''), inventory_id: BASELINKER_INVENTORY_ID, allowed_types: ALLOWED_TYPES, roles: ROLES, job_id: jobId, auth } }];

// Zadanie istnieje, należy do zalogowanego, czeka w kolejce, ma znany typ, a użytkownik ma do niego rolę
const rowsOf = items => items.flatMap(i => Array.isArray(i.json) ? i.json : (i.json && Object.keys(i.json).length ? [i.json] : []));
const cfg = $('KONFIGURACJA').first().json;
const user = $('Sprawdź użytkownika').first().json;
const job = rowsOf($('Pobierz zadanie').all())[0] || null;
const role = (rowsOf($input.all())[0] || {}).role || null;
let reason = null;
if (!job) reason = 'Zadanie nie istnieje';
else if (job.created_by !== user.id) reason = 'Zadanie należy do innego użytkownika';
else if (job.status !== 'w_kolejce') reason = `Zadanie ma status "${job.status}", a nie "w_kolejce"`;
else if (!cfg.allowed_types.includes(job.job_type)) reason = `Nieobsługiwany typ zadania: ${job.job_type}`;
else if (cfg.roles[job.job_type] && !cfg.roles[job.job_type].includes(role)) reason = 'To zadanie może uruchomić akceptujący lub admin';
else if (job.job_type.startsWith('bl_') && !cfg.inventory_id) reason = 'n8n: brak BASELINKER_INVENTORY_ID w node KONFIGURACJA';
return [{ json: { ok: !reason, reason, job, user_id: user.id, user_email: user.email, role } }];

// Zadanie testowe: potwierdza pełny obieg aplikacja → n8n → baza
const c = $('Sprawdź zadanie').first().json;
return [{ json: { result: { message: 'n8n odebrał zadanie i zapisał wynik w bazie', user_email: c.user_email, role: c.role, n8n_time: new Date().toISOString(), execution_id: $execution.id } } }];

// Nowy przebieg synchronizacji indeksu: ID przebiegu (batch_id) + parametry dla BL
const cfg = $('KONFIGURACJA').first().json;
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const batch_id = `${hex(8)}-${hex(4)}-4${hex(3)}-${'89ab'[Math.floor(Math.random() * 4)]}${hex(3)}-${hex(12)}`;
return [{ json: { batch_id, parameters: JSON.stringify({ inventory_id: cfg.inventory_id }) } }];

// Lista katalogu: strony po 1000 produktów (z wariantami). Puste strony na końcu są pomijane przy zbieraniu.
const cfg = $('KONFIGURACJA').first().json;
const p = $('Sprawdź zadanie').first().json.job.payload || {};
const n = Math.min(Math.max(Number(p.max_pages) || 40, 1), 100);
return Array.from({ length: n }, (_, i) => ({ json: { page: i + 1, parameters: JSON.stringify({ inventory_id: cfg.inventory_id, page: i + 1, include_variants: true }) } }));

// Kategorie + producenci + lista produktów → wiersze do zapisu (paczki po 2000)
function blJson(raw) {
  let r = raw;
  if (r && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
  if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) {} }
  return r || {};
}
const start = $('CL: start').first().json;
const now = new Date().toISOString();
const warnings = [];
const bad = r => r.status !== 'SUCCESS';
const errText = r => r.error_message ? `${r.error_message} (${r.error_code || 'brak kodu'})` : 'nieoczekiwana odpowiedź: ' + JSON.stringify(r).slice(0, 200);

const cr = blJson($('BL: kategorie').first().json);
if (bad(cr)) throw new Error('Baselinker – kategorie: ' + errText(cr));
const mr = blJson($('BL: producenci').first().json);
if (bad(mr)) throw new Error('Baselinker – producenci: ' + errText(mr));

const cats = (cr.categories || []).map(c => ({ id: Number(c.category_id), name: String(c.name || '').trim(), parent: Number(c.parent_id) || 0 })).filter(c => c.id);
const byId = new Map(cats.map(c => [c.id, c]));
const pathOf = c => { const parts = []; const seen = new Set(); let x = c; while (x && !seen.has(x.id)) { seen.add(x.id); parts.unshift(x.name); x = byId.get(x.parent); } return parts.join(' > '); };
const catRows = cats.map(c => ({ bl_category_id: c.id, name: c.name, parent_id: c.parent || null, path: pathOf(c), synced_at: now }));

const manRows = (mr.manufacturers || []).map(m => ({ bl_manufacturer_id: Number(m.manufacturer_id), name: String(m.name || m.manufacturer_name || '').trim(), synced_at: now })).filter(m => m.bl_manufacturer_id && m.name);
if (manRows.length >= 10000) warnings.push('Baselinker zwrócił 10 000 producentów – możliwe, że nie wszystkich.');

// lista: każda strona musi się udać, inaczej indeks byłby niepełny (i usunęlibyśmy istniejące wiersze)
const pages = $input.all().map(i => blJson(i.json));
const failed = pages.find(bad);
if (failed) throw new Error('Baselinker – lista produktów: ' + errText(failed));
const seen = new Set(), rows = [];
let lastLen = 0;
for (const r of pages) {
  const list = Object.entries(r.products || {});
  if (list.length) lastLen = list.length;
  for (const [id, x] of list) {
    const bl = Number(x.id || id);
    if (!bl || seen.has(bl)) continue;
    seen.add(bl);
    rows.push({ bl_id: bl, parent_id: Number(x.parent_id) || null, sku: String(x.sku || '').trim() || null, ean: String(x.ean || '').trim() || null, name: String(x.name || '').trim().slice(0, 500), batch_id: start.batch_id, synced_at: now });
  }
}
if (!rows.length) throw new Error('Baselinker nie zwrócił żadnych produktów – sprawdź BASELINKER_INVENTORY_ID');
const fullPages = pages.filter(r => Object.keys(r.products || {}).length >= 1000).length;
const truncated = fullPages >= pages.length;
if (truncated) warnings.push(`Pobrano ${pages.length} pełnych stron – katalog może być większy. Zwiększ max_pages; nieaktualnych produktów nie usunięto.`);

const out = [];
if (catRows.length) out.push({ json: { table: 'bl_categories', conflict: 'bl_category_id', rows: catRows } });
if (manRows.length) out.push({ json: { table: 'bl_manufacturers', conflict: 'bl_manufacturer_id', rows: manRows } });
for (let i = 0; i < rows.length; i += 2000) out.push({ json: { table: 'bl_catalog', conflict: 'bl_id', rows: rows.slice(i, i + 2000) } });
out[0].json.summary = { batch_id: start.batch_id, count: rows.length, categories: catRows.length, manufacturers: manRows.length, truncated, warnings };
return out;

// Wszystkie paczki zapisane? Dopiero wtedy wolno usunąć z indeksu produkty, których nie ma już w BL.
const expected = $('CL: zbierz').all().length;
const got = $input.all().length;
if (got !== expected) throw new Error(`Zapis indeksu niepełny (${got} z ${expected} paczek) – nic nie usunięto, uruchom ponownie`);
const s = $('CL: zbierz').first().json.summary;
return [{ json: { batch_id: s.batch_id, skip_delete: !!s.truncated } }];

const s = $('CL: zbierz').first().json.summary;
const removed = $input.all().filter(i => i.json && i.json.bl_id).length;
return [{ json: { result: { batch_id: s.batch_id, count: s.count, categories: s.categories, manufacturers: s.manufacturers, removed, truncated: s.truncated, warnings: s.warnings } } }];

// Dociągnięcie kategorii i producenta: ID z aplikacji → paczki po 100 dla getInventoryProductsData
const cfg = $('KONFIGURACJA').first().json;
const p = $('Sprawdź zadanie').first().json.job.payload || {};
const ids = [...new Set((Array.isArray(p.ids) ? p.ids : []).map(Number).filter(n => Number.isInteger(n) && n > 0))];
if (!ids.length) throw new Error('Brak ID produktów do uzupełnienia');
if (ids.length > 1000) throw new Error('Maksymalnie 1000 ID w jednym zadaniu');
if (!/^[0-9a-f-]{36}$/i.test(String(p.batch_id || ''))) throw new Error('Brak batch_id przebiegu indeksu');
const out = [];
for (let i = 0; i < ids.length; i += 100) out.push({ json: { parameters: JSON.stringify({ inventory_id: cfg.inventory_id, products: ids.slice(i, i + 100) }) } });
return out;

// Odpowiedzi BL → kategoria, producent, bundle, tagi, produkt nadrzędny (pozostałe kolumny indeksu bez zmian)
function blJson(raw) {
  let r = raw;
  if (r && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
  if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) {} }
  return r || {};
}
const p = $('Sprawdź zadanie').first().json.job.payload || {};
const now = new Date().toISOString();
const rows = [];
for (const it of $input.all()) {
  const r = blJson(it.json);
  if (r.status !== 'SUCCESS') throw new Error('Baselinker: ' + (r.error_message ? `${r.error_message} (${r.error_code || 'brak kodu'})` : 'nieoczekiwana odpowiedź: ' + JSON.stringify(r).slice(0, 200)));
  for (const [id, x] of Object.entries(r.products || {})) {
    rows.push({ bl_id: Number(id), batch_id: p.batch_id, parent_id: Number(x.parent_id) || null, bl_category_id: Number(x.category_id) || null, bl_manufacturer_id: Number(x.manufacturer_id) || null,
      is_bundle: !!x.is_bundle, tags: Array.isArray(x.tags) ? x.tags.map(String) : [], enriched_at: now });
  }
}
const asked = new Set((p.ids || []).map(Number));
const missing = [...asked].filter(id => !rows.some(r => r.bl_id === id));
return [{ json: { rows: rows.filter(r => asked.has(r.bl_id)), missing } }];

// Import wybranych produktów: pełne dane z getInventoryProductsData (paczki po 100)
const cfg = $('KONFIGURACJA').first().json;
const p = $('Sprawdź zadanie').first().json.job.payload || {};
const ids = [...new Set((Array.isArray(p.ids) ? p.ids : []).map(Number).filter(n => Number.isInteger(n) && n > 0))];
if (!ids.length) throw new Error('Brak produktów do importu');
if (ids.length > 300) throw new Error('Maksymalnie 300 produktów w jednym zadaniu importu');
const out = [];
for (let i = 0; i < ids.length; i += 100) out.push({ json: { parameters: JSON.stringify({ inventory_id: cfg.inventory_id, products: ids.slice(i, i + 100) }) } });
return out;

// Odpowiedź BL → wiersze produktów (bez marki – ta po zapisie słownika marek) + uwagi do jakości danych
function blJson(raw) {
  let r = raw;
  if (r && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
  if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) {} }
  return r || {};
}
const p = $('Sprawdź zadanie').first().json.job.payload || {};
const now = new Date().toISOString();
const asked = [...new Set((p.ids || []).map(Number))];
const plain = h => String(h || '').replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const hash = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
const featuresOf = f => {
  if (Array.isArray(f)) f = Object.fromEntries(f.map(x => Array.isArray(x) ? [x[0], x[1]] : [x && x.name, x && x.value]));
  return Object.fromEntries(Object.entries(f || {}).filter(([k, v]) => String(k || '').trim() && v !== null && v !== undefined && String(v).trim() !== '').map(([k, v]) => [String(k).trim(), String(v).trim()]));
};
const found = {}, skipped = [], warnings = [];
for (const it of $input.all()) {
  const r = blJson(it.json);
  if (r.status !== 'SUCCESS') throw new Error('Baselinker: ' + (r.error_message ? `${r.error_message} (${r.error_code || 'brak kodu'})` : 'nieoczekiwana odpowiedź: ' + JSON.stringify(r).slice(0, 200)));
  Object.assign(found, r.products || {});
}
const rows = [];
for (const id of asked) {
  const x = found[id];
  if (!x) { skipped.push({ bl_id: id, reason: 'brak produktu w Baselinkerze (usunięty?)' }); continue; }
  const tf = x.text_fields || {};
  const sku = String(x.sku || '').trim();
  const name = String(tf.name || '').trim();
  if (!sku) { skipped.push({ bl_id: id, reason: 'produkt bez SKU' }); continue; }
  if (!name) { skipped.push({ bl_id: id, sku, reason: 'produkt bez nazwy' }); continue; }
  const description = String(tf.description || '');
  const features = featuresOf(tf.features);
  const description_extra = Object.fromEntries([1, 2, 3, 4].map(n => [`description_extra${n}`, String(tf[`description_extra${n}`] || '')]).filter(([, v]) => v.trim()));
  const extra_fields = Object.fromEntries(Object.entries(tf).filter(([k]) => /^extra_field_\d+$/.test(k)).map(([k, v]) => [k.replace('extra_field_', ''), v]));
  const images = Object.entries(x.images || {}).filter(([k, v]) => /^\d+$/.test(k) && v).sort((a, b) => Number(a[0]) - Number(b[0])).map(([k, v]) => ({ url: String(v), position: Number(k), role: null }));
  const bundle_items = x.is_bundle ? Object.entries(x.bundle_products || {}).map(([bid, q]) => ({ bl_id: Number(bid), quantity: Number(q) || 1 })) : [];
  const dims = { height: Number(x.height) || 0, width: Number(x.width) || 0, length: Number(x.length) || 0 };
  const weight = x.weight === undefined || x.weight === null || x.weight === '' ? null : Number(x.weight);
  const ean = String(x.ean || '').trim() || null;
  const flags = [];
  const descLen = plain(description).length;
  if (!descLen) flags.push('Brak opisu w BL');
  else if (descLen < 300) flags.push(`Krótki opis (${descLen} zn.)`);
  if (!Object.keys(features).length) flags.push('Brak parametrów');
  if (!ean) flags.push('Brak EAN');
  if (weight === null || weight <= 0.05) flags.push(`Waga nieuzupełniona (${weight ?? 'brak'} kg)`);
  if (!images.length) flags.push('Brak zdjęć');
  if (!Number(x.category_id)) flags.push('Brak kategorii');
  if (!Number(x.manufacturer_id)) flags.push('Brak producenta');
  if (x.is_bundle && !bundle_items.length) flags.push('Zestaw bez składników');
  rows.push({
    baselinker_product_id: id, sku, ean, name, description_pl: description, description_extra, features, extra_fields,
    bl_category_id: Number(x.category_id) || null, bl_parent_id: Number(x.parent_id) || null, is_bundle: !!x.is_bundle, bundle_items, images,
    weight, dimensions: (dims.height || dims.width || dims.length) ? dims : null,
    source_hash: hash(JSON.stringify([name, description, features, description_extra])), import_flags: flags, synced_at: now,
    _manufacturer_id: Number(x.manufacturer_id) || null,
  });
}
// duplikaty w paczce: ten sam SKU (blokowałby zapis) i ten sam EAN (marketplace odrzuci)
const bySku = new Map();
const unique = [];
for (const r of rows) {
  if (bySku.has(r.sku.toLowerCase())) { skipped.push({ bl_id: r.baselinker_product_id, sku: r.sku, reason: `SKU powtarza się w BL (ID ${bySku.get(r.sku.toLowerCase())})` }); continue; }
  bySku.set(r.sku.toLowerCase(), r.baselinker_product_id); unique.push(r);
}
const byEan = {};
unique.forEach(r => { if (r.ean) (byEan[r.ean] = byEan[r.ean] || []).push(r.sku); });
unique.forEach(r => { const o = r.ean ? byEan[r.ean].filter(s => s !== r.sku) : []; if (o.length) r.import_flags.push(`EAN taki sam jak ${o.join(', ')}`); });
const man = [...new Set(unique.map(r => r._manufacturer_id).filter(Boolean))];
const cat = [...new Set(unique.map(r => r.bl_category_id).filter(Boolean))];
return [{ json: { rows: unique, skipped, warnings, manufacturer_ids: man, category_ids: cat,
  q_man: `(${man.length ? man.join(',') : 0})`, q_cat: `(${cat.length ? cat.join(',') : 0})`,
  q_existing: `(baselinker_product_id.in.(${unique.map(r => r.baselinker_product_id).join(',') || 0}),sku.in.(${unique.map(r => '"' + r.sku.replace(/["\\]/g, '') + '"').join(',') || '""'}))` } }];

// Producenci z BL → słownik marek aplikacji (marka = producent)
const rowsOf = items => items.flatMap(i => Array.isArray(i.json) ? i.json : (i.json && Object.keys(i.json).length ? [i.json] : []));
const mans = rowsOf($input.all()).filter(m => m.bl_manufacturer_id && m.name);
// jedna marka na nazwę (dwóch producentów o tej samej nazwie zablokowałoby zapis)
const byName = new Map();
for (const m of mans) { const n = String(m.name).trim(); if (!byName.has(n.toLowerCase())) byName.set(n.toLowerCase(), { name: n, bl_manufacturer_id: Number(m.bl_manufacturer_id) }); }
return [{ json: { rows: [...byName.values()] } }];

// Marka, znane kategorie, kolizje SKU z innymi produktami → wiersze do zapisu
const rowsOf = items => items.flatMap(i => Array.isArray(i.json) ? i.json : (i.json && Object.keys(i.json).length ? [i.json] : []));
const src = $('IM: produkty').first().json;
const brands = rowsOf($('SB: marki').all());
const knownCats = new Set(rowsOf($('SB: kategorie').all()).map(c => Number(c.bl_category_id)));
const existing = rowsOf($input.all());
const brandOf = new Map(brands.filter(b => b.bl_manufacturer_id).map(b => [Number(b.bl_manufacturer_id), b.id]));
const existingIds = new Set(existing.map(e => Number(e.baselinker_product_id)));
const skuOwner = new Map(existing.map(e => [String(e.sku).toLowerCase(), Number(e.baselinker_product_id)]));
const skipped = [...src.skipped];
const rows = [];
for (const r of src.rows) {
  const owner = skuOwner.get(r.sku.toLowerCase());
  if (owner && owner !== r.baselinker_product_id) { skipped.push({ bl_id: r.baselinker_product_id, sku: r.sku, reason: `SKU jest już w aplikacji przy innym produkcie BL (ID ${owner})` }); continue; }
  const { _manufacturer_id, ...row } = r;
  row.brand_id = _manufacturer_id ? (brandOf.get(_manufacturer_id) || null) : null;
  if (_manufacturer_id && !row.brand_id) row.import_flags = [...row.import_flags, 'Producent spoza indeksu – odśwież indeks katalogu'];
  if (row.bl_category_id && !knownCats.has(row.bl_category_id)) { row.import_flags = [...row.import_flags, `Kategoria ${row.bl_category_id} spoza indeksu – odśwież indeks katalogu`]; row.bl_category_id = null; }
  rows.push(row);
}
const created = rows.filter(r => !existingIds.has(r.baselinker_product_id)).length;
return [{ json: { rows, skipped, created, updated: rows.length - created, warnings: src.warnings } }];
